namespace RonSijm.FluidHumidifier.Factories.FSx;

public class S3AccessPointAttachmentFactory(string resourceName = null, Action<Humidifier.FSx.S3AccessPointAttachment> factoryAction = null) : ResourceFactory<Humidifier.FSx.S3AccessPointAttachment>(resourceName)
{

    internal InnerS3AccessPointAttachmentS3AccessPointOpenZFSConfigurationFactory OpenZFSConfigurationFactory { get; set; }

    internal InnerS3AccessPointAttachmentS3AccessPointFactory S3AccessPointFactory { get; set; }

    internal InnerS3AccessPointAttachmentS3AccessPointOntapConfigurationFactory OntapConfigurationFactory { get; set; }

    protected override Humidifier.FSx.S3AccessPointAttachment Create()
    {
        var s3AccessPointAttachmentResult = CreateS3AccessPointAttachment();
        factoryAction?.Invoke(s3AccessPointAttachmentResult);

        return s3AccessPointAttachmentResult;
    }

    private Humidifier.FSx.S3AccessPointAttachment CreateS3AccessPointAttachment()
    {
        var s3AccessPointAttachmentResult = new Humidifier.FSx.S3AccessPointAttachment
        {
            GivenName = InputResourceName,
        };

        return s3AccessPointAttachmentResult;
    }
    public override void CreateChildren(Humidifier.FSx.S3AccessPointAttachment result)
    {
        base.CreateChildren(result);

        result.OpenZFSConfiguration ??= OpenZFSConfigurationFactory?.Build();
        result.S3AccessPoint ??= S3AccessPointFactory?.Build();
        result.OntapConfiguration ??= OntapConfigurationFactory?.Build();
    }

} // End Of Class

